(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["eo"] = {"ui":{"skip":"Salti al la enhavo","back":"← Reen al AI-gile","lang.button":"Lingvo: {name}","lang.dialog":"Elektu lingvon","lang.search":"Serĉi lingvojn","lang.none":"Neniu lingvo kongruas","lang.notYet":"{name} ankoraŭ ne estas tradukita","theme.aria":"Ŝanĝi inter hela kaj malhela etoso","theme.toLight":"Ŝanĝi al hela etoso","theme.toDark":"Ŝanĝi al malhela etoso","words.underline":"Substreki ĉi tiujn vortojn en la paĝo","words.underlineHelp":"Ŝvebu super punktita vorto aŭ tuŝetu ĝin por vidi, kion ĝi signifas.","index.title":"AI-gile: via AI-programista teamo, sur unu tabulo","index.description":"AI-gile estas kanban-tabulo por teamoj de AI-programado. Ili laboras dum vi dormas; vi ricevas unu mallongan stakon da aferoj por decidi, testi kaj akcepti.","hero.logoAlt":"Piktogramo de la tabulo AI-gile","hero.h1.html":"Via AI-programista teamo, sur unu&nbsp;tabulo.","hero.alpha":"🐣 Fermita antaŭ-alfao","hero.alphaTitle":"Frua kaj nefinita: dankon pro la provo!","hero.lede":"Ili konstruas dum vi dormas. Vi vekiĝas al unu mallonga stako: kelkaj demandoj, kelkaj aferoj por testi, unu aŭ du purpuraj rombetoj. Alklaku, akceptu, reen al via kafo.","dl.windows":"Apo por Vindozo","dl.browser":"Uzu ĝin en la retumilo","dl.soon":"Baldaŭ","dl.notify":"🔔 Sciigu min kiam ĝi malfermiĝos","dl.notifySmall":"Alfao aŭ beto","hero.secondary":"Facilmova, sed la teamo neniam bezonas stand-up-kafon. (Stand-up-ojn ili tamen faras.)","pitch.h2":"AI-gile en tiom da vortoj, kiom vi volas","pitch.lede":"Elektu longon, de unu vorto ĝis 144. Ĉiu longo estas propra priskribo, verkita por tiu grandeco. Trenu la ŝovilon aŭ uzu la sagoklavojn.","pitch.rangeLabel":"Longo en vortoj","pitch.dice":"🎲 alia versio","pitch.words.one":"{n} vorto","pitch.words.other":"{n} vortoj","pitch.letters.one":"{n} litero","pitch.letters.other":"{n} literoj","pitch.chars.one":"{n} signo","pitch.chars.other":"{n} signoj","count.line.html.one":"{n} karto nun sur la tabulo","count.line.html.other":"{n} kartoj nun sur la tabulo","features.aria":"Kion ĝi faras","f.pile.h":"Unu stako por vi","f.pile.html":"<b>Por vi</b> kolektas ĉion, kio atendas vin, tra ĉiuj projektoj: demandoj, aferoj por testi, taskoj kiujn povas fari nur homo. Via vico diras, kio venas poste kaj kiom longe ĝi daŭras.","f.sleep.h":"Teamoj, kiuj laboras dum vi dormas","f.sleep.p":"Ĉiu projekto havas teamestron kaj teamon de AI-agentoj. Komentu karton kaj la teamo vekiĝas, faras la laboron kaj redonas ĝin kun paŝoj, kiujn laca homo povas sekvi.","f.tester.h":"AI-testanto kontrolas unue","f.tester.p":"Antaŭ ol io atingas vin, testanto sekvas la paŝojn en kopio de la apo kaj montras, kion ĝi vidis, kun ekrankopio. Foliumu la sukcesintajn kaj akceptu per unu klako.","f.proof.h":"Pruvoj, ne promesoj","f.proof.p":"Ĉiu transdono montras, kio ŝanĝiĝis: la dosierojn, la diferencon, la ekrankopiojn. Ne necesas malfermi ĉiun apon por vidi ĉu ĝi pretas.","f.chat.h":"Babilu kun viaj teamestroj","f.chat.p":"Flanka stango en la stilo de Discord: unu piktogramo por projekto, purpuraj rombetoj por tio, kio bezonas vin. Skribu ideon al teamestro; li faras el ĝi kartojn kaj planon, kun butono ✅ Ek.","f.tidy.h":"Ordigas sin mem","f.tidy.p":"Rilataj kartoj kuniĝas, konfuzaj titoloj riparas, kaj kontrolo de ĵetonoj tenas la kodon svelta. Malpli da aferoj inter kiuj ŝanĝi, malpli por pensi.","f.private.h":"Via, en via komputilo","f.private.li1":"La tabulo funkcias en via propra maŝino kaj respondas nur al vi.","f.private.li2":"Privataj mesaĝoj inter homoj estas tutvoje ĉifritaj.","f.private.li3":"Neniuj kontoj, neniuj spuriloj, neniuj kuketoj.","f.lang.h":"En via lingvo","f.lang.p":"Pli ol 120 lingvoj, de la nederlanda, kimra kaj japana ĝis la pirata, Yoda kaj klingona, kun rapida reveno al la angla por la programistaj vortoj.","tl.aria":"Templinio de la unua konversacio ĝis la vojmapo","tl.h2":"De la unua babilo ĝis tio, kio venas","tl.lede":"Veraj datoj kaj horoj, en via propra horzono. Post hodiaŭ temas pri la plano, sen promesitaj datoj.","tl.today":"Hodiaŭ","tl.planned":"planita","tl.cards.one":"{n} karto","tl.cards.other":"{n} kartoj","join.h2":"Aliĝu","join.lede":"AI-gile estas konstruata de eta homo kaj granda nombro da pacientaj agentoj. Nuntempe ĝi estas privata, en fermita alfao kun amikoj. Ĉu vi volas provi, kiam ĝi malfermiĝos?","join.btn":"Registri intereson","join.small":"Ni skribos al vi retpoŝte, nenion plian","footer.tag":"AI-gile. Neniuj spuriloj, neniuj kuketoj, neniu stand-up-kafo.","footer.licence":"Entreprena licenco","footer.status":"Stato","footer.privacy":"Kion ni konservas","form.sending":"Sendado…","form.failed":"Tio ne funkciis: reprovu poste.","form.offline":"Ne eblis atingi AI-gile: reprovu poste.","form.keep":"Ni uzas tion nur por respondi al vi, poste ni forigas ĝin. Neniuj spuriloj, neniuj kuketoj.","form.keepLink":"Kion ni konservas","interest.title":"AI-gile: sciigu min kiam la alfao malfermiĝos","interest.description":"Lasu vian retpoŝton por scii, kiam la fermita alfao aŭ beto de AI-gile malfermiĝos.","interest.h1":"🔔 Sciigu min kiam ĝi malfermiĝos","interest.lede":"AI-gile estas en fermita antaŭ-alfao. Lasu vian retpoŝton kaj ni skribos unu fojon, kiam estos loko por vi.","interest.email":"Via retpoŝto","interest.which":"Kiu testo?","interest.alpha":"Fermita alfao: frua, malglata, multaj ŝanĝoj","interest.beta":"Beto: pli stabila, pli malfrue","interest.both":"Ambaŭ, kiu ajn venos unue","interest.submit":"Metu min en la liston","interest.thanks":"Dankon! Vi estas en la listo.","licence.title":"AI-gile: entreprena licenco","licence.description":"Ĉu vi uzas AI-gile en via entrepreno? Petu senpagan entreprenan licencon.","licence.h1":"📜 Entreprena licenco","licence.lede":"Ĉu vi uzas AI-gile en la laboro? Diru al ni, kiu vi estas kaj kion vi faras. Se ĝi faras iom da bono, la licenco estas senpaga.","licence.company":"Firmao","licence.website":"Retejo","licence.what":"Kion vi faras","licence.how":"Kiel ĝi helpas la mondon","licence.email":"Retpoŝto","licence.submit":"Peti","licence.thanks":"Dankon! Ni respondos retpoŝte.","status.title":"Stato de AI-gile","status.h1":"Stato de AI-gile","status.quiet":"Ĉio trankvilas","status.intro":"Ĉu AI-gile funkcias ĝuste nun? Ĉi tiu paĝo kontrolas la retejon, la kundividon de tabuloj, la vokojn kaj la elŝuton ĉiujn 5 minutojn.","status.up":"Funkcias (respondis en {ms} ms)","status.slow":"Ne respondis al la lasta kontrolo, reprovas","status.down":"Ne funkcias: ne respondis al la lastaj du kontroloj","status.svc.web":"Retejo","status.svc.web.offers":"Ĉi tiu retejo: kio estas AI-gile, kaj la formularo por montri intereson","status.svc.boards":"Kundivido de tabuloj","status.svc.boards.offers":"Publikaj tabuloj, mesaĝoj inter amikoj kaj invitoj","status.svc.calls":"Vokoj","status.svc.calls.offers":"Voĉo, video kaj ekrankundivido en AI-gile","status.svc.download":"Elŝuto","status.svc.download.offers":"La instalilo por Windows kaj invitaj ligiloj","status.checking":"Kontrolado…","status.offline":"Nun ne eblas atingi la stato-servon (reprovas)","status.updated":"ĝisdatigita {ago}","status.justNow":"ĵus","status.min":"antaŭ {n} min","status.hours":"antaŭ {n} h","status.days":"antaŭ {n} t","privacy.title":"AI-gile: kion ni konservas","privacy.h1":"Kion ni konservas","privacy.lede":"Mallonge: nur tion, kion vi sendas al ni, kaj ne longe.","privacy.only":"Nur tion, kion vi sendas al ni: kion vi tajpas en formularon, ekzemple vian retpoŝtadreson. Nenion alian pri vi.","privacy.sealed":"Ĝi estas sigelita, por ke nia servilo ne povu legi ĝin: en via retumilo antaŭ ol ĝi foriras (ĉe pli malnova retumilo, tuj kiam ĝi alvenas). Nur nia propra tabulo povas malfermi ĝin.","privacy.server":"La servilo forigas ĝin tuj kiam ĝi atingas nian tabulon. Kio ankoraŭ restas tie post 30 tagoj, estas forigata ĉiuokaze.","privacy.board":"Ni konservas ĝin en nia tabulo nur ĝis ni respondis al vi, poste ni forigas ĝin ankaŭ tie.","privacy.none":"Neniuj spuriloj, neniuj kuketoj, neniu analizado.","privacy.local":"Via lingvo kaj via elekto inter hela kaj malhela restas en via propra retumilo. Ili neniam estas senditaj al ni.","privacy.ask":"Ĉu vi volas, ke ĝi malaperu pli frue? Respondu al nia retmesaĝo kaj diru tion.","live.h2":"Rigardu ĝin konstruiĝi, rekte","live.caption":"Ĉiu karto estas kaŝita: vi vidas la formon de la laboro, ne la vortojn.","live.watching.one":"rekte: {n} rigardas","live.watching.other":"rekte: {n} rigardas","live.last.now":"Lasta karto movita ĵus","live.last.min.one":"Lasta karto movita antaŭ {n} min","live.last.min.other":"Lasta karto movita antaŭ {n} min","live.last.hour.one":"Lasta karto movita antaŭ {n} horo","live.last.hour.other":"Lasta karto movita antaŭ {n} horoj","live.last.day.one":"Lasta karto movita antaŭ {n} tago","live.last.day.other":"Lasta karto movita antaŭ {n} tagoj","live.offline":"La viva tabulo iom ripozas. Revenu baldaŭ.","live.cols":"Backlog|Farotaj|Farata|Teamo kontrolas|Por ke vi testu|Por la teamo|Farite"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotoj.","Delegite."]},{"n":2,"texts":["Robota kanban.","Agentoj, ordigitaj.","Ideoj, konstruitaj."]},{"n":3,"texts":["Kanban por robotoj.","Ideoj fariĝas funkcioj.","Senpaga agenta kanban."]},{"n":5,"texts":["Kanban-tabulo gvidata de agentoj.","Vi skribas kartojn. Agentoj konstruas.","Senpaga, loka, testita, iom malsaĝa."]},{"n":8,"texts":["Senpaga kanban-tabulo, kie AI-agentoj faras la laboron.","Skribu ideon. Agentoj konstruas ĝin. Vi akceptas.","Facilmova por unu homo kaj multaj pacientaj robotoj."]},{"n":13,"texts":["Kanban-tabulo en via komputilo, kie AI-agentoj prenas la kartojn kaj plenumas ilin.","Skribu ideon. Teamo de agentoj konstruas ĝin. Testanto kontrolas. Vi diras jes.","Senpaga, sen kontoj, sen spuriloj: tabulo, kelkaj robotoj, kaj vi gvidas."]},{"n":21,"texts":["AI-gile estas kanban-tabulo por labori kun AI-programaj agentoj. Ili prenas la kartojn; vi testas kaj akceptas ilin.","Ĉiu projekto ricevas teamestron kaj teamon de AI-agentoj. Komentu ajnan karton kaj la teamo tuj ekklopodas por vi.","Senpaga persona tasktabulo, kiu funkcias en via propra komputilo. La laboristoj estas robotoj. Tiu, kiu diras jes, estas vi."]},{"n":34,"texts":["Vi metas ideojn sur tabulon. Teamo de AI-agentoj igas ilin funkciantaj ecoj, testas ilin kaj redonas ilin al vi kun paŝoj por provi. Nenio validas kiel farita, ĝis vi mem tion diras.","AI-gile estas hejmfarita kanban-tabulo, kiun Rich konstruis kun multe da helpo de la agentoj, kiujn ĝi nun administras. Ĝi estas senpaga, funkcias en via komputilo kaj estas kunhavigata kun amikoj, ne vendata.","Imagu ordinaran kanban-tabulon, kun kolumnoj de Backlog ĝis Farite, sed la kartojn prenas AI-agentoj. Ili raportas progreson, demandas kiam ili blokiĝas, kaj ĉiam atendas vian aprobon antaŭ ol io finiĝas."]},{"n":55,"texts":["AI-gile estas kanban-tabulo, kies teamo konsistas el AI-agentoj. Ĉiu projekto havas teamestron, kiu planas la laboron, kaj helpantojn, kiuj konstruas ĝin. Kiam eco pretas, AI-testanto provas ĝin kaj faras ekrankopion, poste ĝi alvenas en vian stakon. Akceptu ĝin, aŭ komentu kaj ili refaras ĝin.","Ĝi komenciĝis kiel maniero de unu homo kontroli multajn sesiojn de AI-programado samtempe, kaj kreskis en veran tabulon. Ĝi funkcias en via maŝino, postulas neniun konton kaj havas neniujn spurilojn. Ĝi estas senpaga por amikoj kaj scivolemuloj. Ĝi ankaŭ estas nefinita, do atendu malglataĵojn kaj foje surprizon.","Jen la honesta versio. Vi ankoraŭ devas havi la ideojn, kaj vi ankoraŭ devas kontroli la rezultojn. Kion AI-gile faras, estas ĉio inter ili: ĝi tenas la kartojn en ordo, vekas la ĝustan agenton kiam vi komentas, montras precize kio ŝanĝiĝis, kaj metas ĉion en unu mallongan stakon por vi."]},{"n":89,"texts":["AI-gile estas senpaga kanban-tabulo, kiun vi funkciigas en via propra komputilo. Anstataŭ homoj, ĉiu projekto havas teamon de AI-agentoj: teamestron, kiu igas viajn ideojn kartoj kaj plano, kaj helpantojn, kiuj prenas la kartojn laŭ prioritato. Kiam io estas konstruita, AI-testanto sekvas la testpaŝojn kaj montras al vi, kion ĝi vidis. Poste ĝi atendas en unu stako nomata Por vi. Vi akceptas ĝin, aŭ vi komentas kaj la teamo provas denove. Nenio iam atingas Farite sen vi.","Kelkaj aferoj, kiujn vi eble ne atendas. Nokta gardo tenas la kolumnon Farotaj plena dum vi dormas, elektante kartojn, kiuj ne bezonas respondon de vi. Ĵetona kalkulilo montras, kiom la agentoj uzis hodiaŭ kaj ĉi-semajne, kaj Senĵetona Reĝimo diras al ili ĉesi elspezi. Vi povas mesaĝi al amikoj, kaj privataj mesaĝoj estas tutvoje ĉifritaj. La tabulo parolas ĉirkaŭ 120 lingvojn, inkluzive de la nederlanda, flandra, pirata kaj klingona. Nenio el ĝi kostas eĉ centon, kaj neniu provas vendi ĝin al vi.","AI-gile estas eta persona projekto, ne kompanio. Rich volis prizorgi plurajn AI-programajn projektojn sen malfermi ĉiun apon por kontroli ilin, do li kaj la agentoj konstruis tabulon por tio, kaj poste uzis la tabulon por konstrui la reston de si mem. Ĝi estas en fermita antaŭ-alfao, kio signifas, ke ĝi funkcias, plejparte, por manpleno da amikoj. Ne ekzistas prezpaĝo, informletero nek kreskoplano. Se ĝi sonas utila, vi povas peti provi ĝin, kiam ĝi malfermiĝos iom pli."]},{"n":144,"texts":["AI-gile estas kanban-tabulo por unu homo kaj multaj AI-agentoj. Ĝi funkcias en via propra komputilo kaj estas tute senpaga. Vi aldonas projektojn, kaj ĉiu projekto ricevas teamestron kaj malgrandan teamon. Vi babilas kun la teamestro, iom kiel en Discord, kaj priskribas ideon; la teamestro igas ĝin kartoj kaj plano, kaj atendas ĝis vi premos Ek. La teamo laboras tra la kartoj laŭ prioritato, per simpla komandlinio farita por lingvomodeloj. Antaŭ ol io revenas al vi, AI-testanto sekvas la paŝojn en kopio de la apo kaj aldonas ekrankopion. Finita laboro alvenas en vian stakon kun la ŝanĝitaj dosieroj kaj la diferenco. Vi akceptas ĝin, aŭ vi lasas komenton kaj la teamo vekiĝas kaj provas denove. Nur vi povas movi karton al Farite.","Tago kun AI-gile, proksimume. Vespere vi lasas kelkajn komentojn: ĉi tiu butono estas en la malĝusta loko, tiu listo devus esti ordigita, ĉu ni povus havi malhelan reĝimon. Vi iras enlitiĝi. La agentoj legas la komentojn, faras la ŝanĝojn, testas ilin kaj redonas ilin al vi. Se Farotaj malplenas, la nokta gardo replenigas ĝin el la backlog per kartoj, kiuj ne bezonas respondon de vi. Matene estas unu mallonga stako: kelkaj demandoj kaj kelkaj aferoj por provi, ĉiu kun paŝoj, kiujn dormema homo povas sekvi, kaj ekrankopio de ĝia funkciado. Vi klakas tra ili, akceptas la bonajn kaj resendas la reston. Ĵetona kalkulilo montras, kion ĉio uzis, kaj Senĵetona Reĝimo ekzistas por maldikaj semajnoj. Poste vi matenmanĝas, en kio la agentoj ankoraŭ ne povas helpi.","Unue, kio AI-gile ne estas. Ĝi ne estas noventrepreno, ĝi ne estas vendata, kaj neniu kolektas viajn datumojn. Ĝi estas senpaga tabulo, kiu funkcias en via komputilo, sen kontoj, sen spuriloj kaj sen kuketoj. Kio ĝi estas: unu ordigita loko por vidi ĉiujn AI-programajn projektojn samtempe, kun teamo de agentoj, kiu plenumas la kartojn, kaj vi, kiu decidas. Ĝi kunigas rilatajn kartojn, riparas konfuzajn titolojn kaj gardas, kiom svelta la kodo restas. Ĝi parolas ĉirkaŭ 120 lingvojn, de la nederlanda kaj flandra ĝis la pirata kaj klingona. Amikoj povas mesaĝi unu al la alia, private kaj ĉifrite. Ĝin konstruis Rich kaj granda nombro da pacientaj agentoj, plejparte uzante sin mem. Ĝi estas en fermita antaŭ-alfao, do en kelkaj lokoj ĝi estas malglata. Se ĝi sonas amuza, petu afable kaj vi eble eniros frue."]}],"quips":{"1":"Unu vorto. Kuraĝa. Eble tro kuraĝa.","3":"Tri vortoj. Jam pli honesta ol la plej multaj produktaj paĝoj.","8":"Ok vortoj. Ankoraŭ pli mallonga ol stand-up.","21":"La longoj, cetere, estas rakontopunktoj. Kompreneble ili estas.","55":"Kvindek kvin vortoj. Du kartoj finiĝis dum vi legis tion.","144":"Tio estis la longa. Ne ekzistas 233. La agentoj enlitiĝis."}},"timeline":{"first-idea.name":"La unua ideo","first-idea.line":"La plej unua konversacio, antaŭ ol ekzistis kodo.","first-board.name":"Unua tabulo","first-board.line":"Tabulo, kiu sekvas sian propran konstruon: kartoj, kolumnoj, treni kaj lasi, projektoj.","team-roles.name":"Teamo kaj roloj","team-roles.line":"Profiloj de agentoj, teamaj ŝablonoj, spacoj kaj kiu faras kion.","install.name":"Instalado kaj eldonoj","install.line":"Zip-dosiero, kiun amiko povas instali, memĝisdatigo, kanaloj kaj reveno.","usage-saver.name":"Ŝparado de uzado","usage-saver.line":"Mezuri kion kostas la rulado, teni la kodon svelta, ŝpari vian limon.","friends.name":"Amikoj kaj kunhavigo","friends.line":"Privataj mesaĝoj, miksita relajso, invitoj, roloj kaj komunaj projektoj.","languages.name":"Lingvoj","languages.line":"Ĉiuj ekrantekstoj en lingva dosiero, unue la nederlanda kaj la flandra.","ai-tester.name":"AI-testanto","ai-tester.line":"Testanto kontrolas ĉiun transdonon unue kaj montras, kion ĝi vidis.","website.name":"La retejo","website.line":"aigile.lol, la antaŭmontro kaj ĉi tiu templinio.","streaming.name":"Babilo kaj elsendado","streaming.line":"Discord, Twitch, OBS, elsendista reĝimo, GIF-oj kaj emoĝioj.","no-ai.name":"Eldono sen AI","no-ai.line":"Tabulo por homoj, kiuj programas sen AI, kaj publikaj tabuloj.","night-watch.name":"Nokta gardo","night-watch.line":"Gardisto kaj Scrum-Mastro tenas la teamojn ĉe la tasko dum vi dormas.","p-more.name":"Ĉio alia","p-more.line":"Pli malgrandaj ideoj, kiuj ankoraŭ atendas sian vicon.","p-android.name":"Telefono kaj Android","p-android.line":"Atingi vian tabulon de telefono, poste denaska Android-apo.","p-release.name":"Alfao kaj pli","p-release.line":"Fermita alfao, la viva retejo, poste beto.","p-languages.name":"Pli da lingvoj","p-languages.line":"Pli ol cent lingvoj, kaj trempa reĝimo por lernantoj.","p-engines.name":"Pli da AI-motoroj","p-engines.line":"Elektu Claude, Codex aŭ Gemini por ĉiu agento.","p-pro.name":"Profesia praktiko","p-pro.line":"Riskaj etikedoj, kunfandaj pordegoj, incidentaj kartoj kaj gardbarilo.","p-self.name":"Prizorgi vin","p-self.line":"Laca reĝimo, memprizorgaj rememoriloj kaj 4:20.","p-servers.name":"Serviloj kaj kresko","p-servers.line":"Tutmondaj servilaj agordoj, roloj kaj planado por kresko.","p-livestream.name":"Elsendaj aldonaĵoj","p-livestream.line":"Twitch-babilo, propraj emoĝioj kaj publika viva vido."},"words":{"button":"📖 Programistaj vortoj","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Serĉi vorton…","none":"Neniu vorto kongruas.","close":"Fermi","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Deponejo","text":"La dosierujo de la projekto kun kodo kaj ĝia plena historio de enmetoj, kutime ankaŭ tenata en GitHub.","also":["deponejo"]},{"id":"branch","g":"build","word":"Branĉo","text":"Aparta linio de laboro en la kodo, por ke oni povu fari ŝanĝojn sen tuŝi la ĉefan version.","also":["branĉoj"]},{"id":"commit","g":"build","word":"Enmeto","text":"Konservita momentfoto de la kodo, kun mallonga noto pri tio, kio ŝanĝiĝis. Vi ĉiam povas reiri al unu.","also":["enmetoj"]},{"id":"push","g":"build","word":"Puŝo","text":"Sendi konservitajn momentfotojn (enmetojn) de ĉi tiu komputilo al GitHub, por ke ili estu savkopiitaj kaj komunigitaj."},{"id":"merge","g":"build","word":"Kunfandi","text":"Kuniĝi la ŝanĝojn de branĉo reen en la ĉefan version."},{"id":"pr","g":"build","word":"Tira peto","text":"Peti, ke la ŝanĝoj de branĉo estu kontrolitaj kaj kunfanditaj en la ĉefan version.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktorado","text":"Ordigi la kodon sen ŝanĝi kion ĝi faras: pli malgrandaj dosieroj, pli klaraj nomoj, malpli da ripetado."},{"id":"bug","g":"build","word":"Cimo","text":"Io, kio ne funkcias kiel ĝi devus.","also":["cimoj"]},{"id":"test","g":"build","word":"Testo","text":"Provi finitan laboron por kontroli, ke ĝi faras tion, kio estis petita, antaŭ ol vi akceptas ĝin.","also":["testoj"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Disponigi","text":"Publikigi novan version, ekzemple sur servilo, kie homoj uzas ĝin."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Nefarita listo","text":"Ideoj kaj laboro ankoraŭ ne planitaj. Nenio tie estas laborata ĝis ĝi moviĝas al Farotaj."},{"id":"sprint","g":"team","word":"Sprinto","text":"Mallonga laborperiodo (ofte semajno aŭ du) kun interkonsentita aro de kartoj por fini.","also":["sprintoj"]},{"id":"standup","g":"team","word":"Stariĝa kunveno","text":"Rapida enregistriĝo: kion ĉiu teamano faris, kion li faros poste, kaj kio haltigas lin.","also":["stariĝa kunveno","stariĝaj kunvenoj"]},{"id":"kanban","g":"team","word":"Kanban","text":"Tabulo kun kolumnoj (Farotaj, Farata, Farite) kie kartoj moviĝas de maldekstre dekstren dum la laboro okazas."},{"id":"wip","g":"team","word":"WIP-limo","text":"Laboro en progreso: la plej multaj kartoj, kiujn kolumno devus teni, por ke la teamo finu aferojn antaŭ ol komenci pliajn.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agento","text":"AI, kiu laboras memstare pri tasko: legas la kodon, faras ŝanĝojn, rulas kontrolojn kaj raportas reen.","also":["agentoj"]},{"id":"token","g":"team","word":"Ĵetono","text":"La unuo, en kiu AI-uzado estas kalkulata: proksimume kelkaj literoj de teksto legitaj aŭ skribitaj. Pli malmultaj ĵetonoj, pli de via plano restas.","also":["ĵetonoj"]},{"id":"hook","g":"team","word":"Hoko","text":"Eta komando, kiu funkcias memstare en difinita momento, ekz. kiam AI-seanco startas, por ke la teamo aŭdu viajn komentojn.","also":["hokoj"]}]}};
